styles:
.affiliate-notice { background: #f0f4f8; border-left: 4px solid #3498db; padding: 12px 16px; font-size: 0.82em; color: #555; border-radius: 0 6px 6px 0; margin-bottom: 30px; }
.btn-amazon { display: inline-block; background: #ff9900; color: #fff; text-align: center; padding: 10px 18px; border-radius: 6px; text-decoration: none; font-weight: bold; font-size: 0.9em; margin-top: 10px; }
.btn-amazon:hover { background: #e68a00; }

.section-title { font-size: 1.6em; color: #2c3e50; border-bottom: 3px solid #3498db; padding-bottom: 8px; margin: 40px 0 20px; }
.product-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 24px; margin-bottom: 40px; }
.product-card { background: #fff; border-radius: 10px; box-shadow: 0 2px 12px rgba(0,0,0,0.09); padding: 20px; display: flex; flex-direction: column; }
.product-card h3 { font-size: 1em; color: #2c3e50; margin: 0 0 8px; line-height: 1.4; }
.product-card .fit { color: #2c7bb6; font-size: 0.85em; font-weight: 600; margin-bottom: 10px; }
.product-card p { font-size: 0.88em; color: #555; flex-grow: 1; margin-bottom: 14px; }
.btn-amazon { display: block; background: #ff9900; color: #fff; text-align: center; padding: 10px 14px; border-radius: 6px; text-decoration: none; font-weight: bold; font-size: 0.9em; margin-top: auto; }
.btn-amazon:hover { background: #e68a00; }
.affiliate-notice { background: #f0f4f8; border-left: 4px solid #3498db; padding: 12px 16px; font-size: 0.82em; color: #555; border-radius: 0 6px 6px 0; margin-bottom: 30px; }
